      "note": "Chùa Linh Phước rực rỡ từng mảnh sành, cứ thong thả mà ngắm từng bức phù điêu."
    },
    {
      "poi_id": "p9",
      "kind": "activity",
      "must_do_id": null,
      "note": "Ga Trại Mát nhỏ xinh, đứng đó nhìn tàu chầm chậm qua cũng thấy lòng nhẹ tênh."
    },
    {
      "poi_id": "p16",
      "kind": "activity",
      "must_do_id": null,
      "note": "Thiền viện Trúc Lâm yên ắng giữa đồi thông, hít một hơi là thấy cả ngày dài ra."
    },
    {
      "poi_id": "p59",
      "kind": "meal",
      "must_do_id": null,
      "note": "Chill Chill Eatery ngồi êm, gọi món chậm rãi, nhìn phố núi qua ô cửa kính."
    },
    {
      "poi_id": "p144",
      "kind": "activity",
      "must_do_id": null,
      "note": "Marché lên đèn là phố sáng đúng điệu, dạo một vòng cho đêm Đà Lạt thêm phần vui."
    },
    {
      "poi_id": "p139",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lẩu gà lá é nóng hổi, ngồi xuống là muốn gắp thêm miếng nữa, ngon quá."
    }
  ]
}
```

