    },
    {
      "poi_id": "p41",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bánh ướt mềm, lòng gà dai giòn, chan thêm chút nước mắm chua ngọt là đúng bài."
    },
    {
      "poi_id": "p286",
      "kind": "activity",
      "must_do_id": null,
      "note": "Vườn hoa rực rỡ đủ màu, đi chầm chậm ngắm từng luống, chỗ này chụp ảnh đẹp khỏi bàn."
    },
    {
      "poi_id": "p33",
      "kind": "meal",
      "must_do_id": null,
      "note": "Góc nhỏ ấm cúng, món ăn bày đẹp mắt, ngồi xuống là muốn gọi thêm một vòng nữa."
    },
    {
      "poi_id": "p20",
      "kind": "activity",
      "must_do_id": null,
      "note": "Chợ đêm lên đèn, người qua lại rộn ràng, ngửi mùi đồ nướng là chân tự bước theo."
    }
  ]
}
